/* ---------- 世界书 ---------- */
let _worldbookCategoryFilter='all';
function worldbookCategoryRows(){const rows=Array.isArray(S.worldbookCategories)?S.worldbookCategories:[],seen=new Set();return rows.filter(x=>{const id=String(x&&x.id||''),name=String(x&&x.name||'').trim();if(!/^[a-z0-9_-]{1,80}$/i.test(id)||!name||seen.has(id))return false;seen.add(id);return true;});}
function worldbookEntryCategoryId(w){const id=String(w&&w.categoryId||'');return id&&worldbookCategoryRows().some(x=>String(x.id)===id)?id:'';}
function worldbookCategoryName(id){const row=worldbookCategoryRows().find(x=>String(x.id)===String(id||''));return row?String(row.name):'未分类';}
function worldbookCategoryFilterSet(id){id=String(id||'all');if(id!=='all'&&id!=='uncategorized'&&!worldbookCategoryRows().some(x=>String(x.id)===id))id='all';_worldbookCategoryFilter=id;render();}
function worldbookCategoryFilteredRows(){const all=S.worldbook||[],id=_worldbookCategoryFilter;if(id==='all')return all.slice();if(id==='uncategorized')return all.filter(w=>!worldbookEntryCategoryId(w));return all.filter(w=>worldbookEntryCategoryId(w)===id);}
function worldbookCategoryCleanName(v){return String(v||'').replace(/\s+/g,' ').trim().slice(0,24);}
function worldbookCategoryNameError(name,skipId){if(!name)return'请填写分类名称';if(name==='全部'||name==='未分类')return'“全部”和“未分类”是系统筛选名称';if(worldbookCategoryRows().some(x=>String(x.id)!==String(skipId||'')&&String(x.name).toLowerCase()===name.toLowerCase()))return'已经有同名分类';return'';}
function worldbookModal(html){openModal(html);const m=$('#modal');if(!m)return;m.classList.add('worldbook-modal','dy-solid-modal');m.classList.remove('gamehub-modal','dy-solid-light','dy-solid-wx','dy-solid-dy','dy-solid-pet');}
// WORLDBOOK_ARCHIVE_V1: real archive actions and counts; grouping never changes injection order.
let _worldbookSearch='';
function worldbookAttr(value){return esc(value).replace(/"/g,'&quot;').replace(/'/g,'&#39;');}
function worldbookActionId(id){return worldbookAttr(JSON.stringify(String(id)));}

function worldbookSearchSet(value){_worldbookSearch=String(value||'').slice(0,200);const old=$('#wb_search'),pos=old&&old.selectionStart;render();const el=$('#wb_search');if(el){el.focus();if(pos!=null)el.setSelectionRange(pos,pos);}}
function worldbookIconIndex(w){const n=String(w&&w.name||'');return /微信|电话|朋友圈/.test(n)?2:/扮演|角色|身份/.test(n)?3:/约会|恋爱/.test(n)?4:/小黑屋|禁闭|密室|锁/.test(n)?5:/游戏|怪谈|剧场/.test(n)?6:7;}
function worldbookScopesOn(){return WORLD_SCOPE_OPTIONS.some(([k])=>worldbookScopeOn(k));}
function worldbookScopesToggle(){S.settings=S.settings||{};if(worldbookScopesOn()){S.settings._worldbookAppsBeforePause=Object.fromEntries(WORLD_SCOPE_OPTIONS.map(([k])=>[k,worldbookScopeOn(k)]));S.settings.worldbookApps=Object.fromEntries(WORLD_SCOPE_OPTIONS.map(([k])=>[k,false]));}else{const old=S.settings._worldbookAppsBeforePause;S.settings.worldbookApps=old&&WORLD_SCOPE_OPTIONS.some(([k])=>old[k]!==false)?{...old}:Object.fromEntries(WORLD_SCOPE_OPTIONS.map(([k])=>[k,true]));delete S.settings._worldbookAppsBeforePause;}save();render();}
function worldbookScopeSettings(){worldbookModal(`<h3>允许这些软件吃世界书</h3><div class="hint">按软件选择共享范围。停用软件后，该软件不会读取世界书；不会删除档案。</div><div class="section">${WORLD_SCOPE_OPTIONS.map(([k,t])=>`<label class="avline"><span>${esc(t)}</span><button type="button" class="sw ${worldbookScopeOn(k)?'on':''}" role="switch" aria-checked="${worldbookScopeOn(k)}" aria-label="${esc(t)}使用世界书" onclick="worldbookScopeToggle('${k}')"></button></label>`).join('')}</div><button class="btn p" onclick="closeModal()">完成</button>`);}
function worldbookScopeToggle(k){toggleWorldScope(k);worldbookScopeSettings();}
function worldbookHelp(){worldbookModal(`<h3>世界书使用说明</h3><div class="wb-help"><p>世界书 = 给所有角色共享的设定/常识。已启用的“常驻”档案每次生效；“关键词”档案在对话命中关键词时注入。可为每本档案指定作用角色。</p><p>“常用档案”是你手动置顶的收藏，和“常驻”触发方式是两件事；置顶、分类与搜索只改变列表，不改变注入顺序或触发规则。</p><p>分类只方便你整理和查看，不会改变作用角色与生效范围。</p><p>支持导入 TXT、MD、JSON，导入只会追加，不会覆盖现有内容；TXT/MD 会作为一条常驻世界书。导入默认进入“未分类”，重复内容会跳过。</p><p>顶上的“本 / 启用”只计算真实世界书。“允许这些软件吃世界书”是共享范围设置，不占世界书本数；它的总开关停用后，再打开会恢复你原先的软件选择。</p></div><button class="btn p" onclick="closeModal()">知道了</button>`);}
function worldbookPinToggle(id){const w=(S.worldbook||[]).find(x=>x.id===id);if(!w)return;w.pinned=!w.pinned;save();closeModal();render();}
function worldbookDuplicate(id){const w=(S.worldbook||[]).find(x=>x.id===id);if(!w)return;S.worldbook.push({...w,id:uid(),name:String(w.name||'未命名')+'（副本）',enabled:false,contacts:(w.contacts||[]).slice()});save();closeModal();render();toast('已复制，副本默认停用');}
function worldbookExport(id){const w=(S.worldbook||[]).find(x=>x.id===id);if(!w)return;downloadBlob(new Blob([JSON.stringify({worldbook:[w]},null,2)],{type:'application/json'}),String(w.name||'世界书').replace(/[\\/:*?"<>|]/g,'_')+'.json');}
async function worldbookDeleteAsk(id){const w=(S.worldbook||[]).find(x=>x.id===id);if(!w)return;if(await uiConfirm('删除世界书“'+(w.name||'未命名')+'”？内容将从当前档案库移除。',{danger:true,yes:'删除'}))delWorld(id);}
function worldbookEntryMenu(id){const w=(S.worldbook||[]).find(x=>x.id===id);if(!w)return;const j=worldbookActionId(id);worldbookModal(`<h3>${esc(w.name||'未命名')}</h3><div class="wb-menu"><button class="btn g" onclick="editWorld(${j})">编辑内容、分类与触发方式</button><button class="btn g" onclick="worldbookPinToggle(${j})">${w.pinned?'移出常用档案':'设为常用档案'}</button><button class="btn g" onclick="worldbookDuplicate(${j})">复制档案（副本默认停用）</button><button class="btn g" onclick="worldbookExport(${j})">导出 JSON</button><button class="btn d" onclick="worldbookDeleteAsk(${j})">删除档案</button></div><button class="btn g" onclick="closeModal()">取消</button>`);}
function renderWorldbook(){
 const categories=worldbookCategoryRows();if(_worldbookCategoryFilter!=='all'&&_worldbookCategoryFilter!=='uncategorized'&&!categories.some(x=>String(x.id)===_worldbookCategoryFilter))_worldbookCategoryFilter='all';
 const all=(S.worldbook||[]).filter(Boolean),q=_worldbookSearch.trim().toLocaleLowerCase(),rows=worldbookCategoryFilteredRows().filter(w=>!q||[w.name,w.content,w.keys,worldbookCategoryName(w.categoryId)].join('\n').toLocaleLowerCase().includes(q)),pinned=rows.filter(w=>w.pinned),other=rows.filter(w=>!w.pinned),system=_worldbookCategoryFilter==='all'&&(!q||'允许这些软件吃世界书 系统 共享范围'.includes(q));
 const count=id=>id==='all'?all.length:id==='uncategorized'?all.filter(w=>!worldbookEntryCategoryId(w)).length:all.filter(w=>worldbookEntryCategoryId(w)===id).length,chip=(id,label)=>`<button type="button" class="${_worldbookCategoryFilter===id?'on':''}" aria-pressed="${_worldbookCategoryFilter===id}" onclick="worldbookCategoryFilterSet('${id}')">${id==='all'?'<span class="wb-paw"><svg viewBox="0 0 24 24"><ellipse cx="5" cy="7" rx="2.3" ry="3"/><ellipse cx="11" cy="4" rx="2.3" ry="3"/><ellipse cx="17" cy="7" rx="2.3" ry="3"/><ellipse cx="21" cy="12" rx="2" ry="2.8"/><path d="M5 17q1-5 6-5t7 5q3 6-4 4-3-1-5 0-6 2-4-4Z"/></svg></span> ':''}${esc(label)} ${count(id)}</button>`;
 const card=w=>{const id=worldbookActionId(w.id),category=worldbookEntryCategoryId(w);return `<article class="wb-row" data-world-id="${worldbookAttr(w.id)}"><button type="button" class="wb-row-main" onclick="editWorld(${id})"><i class="wb-art wb-art-${worldbookIconIndex(w)}" aria-hidden="true"></i><span><b>${esc(w.name||'未命名')}</b><small>${esc(String(w.content||'').replace(/\s+/g,' ').slice(0,110)||'还没有填写内容')}</small></span></button><div class="wb-tags"><button type="button" onclick="editWorld(${id})">${w.always?'常驻':'关键词'}</button><button type="button" class="category" onclick="editWorld(${id})">${esc(category?worldbookCategoryName(category):'未分类')}</button></div><button type="button" class="wb-switch ${w.enabled?'on':''}" role="switch" aria-checked="${!!w.enabled}" aria-label="启用${worldbookAttr(w.name||'未命名')}" onclick="toggleWorld(${id})"><i></i></button><button type="button" class="wb-more" aria-label="${worldbookAttr(w.name||'未命名')}更多操作" onclick="worldbookEntryMenu(${id})">···</button></article>`;};
 return `<div class="worldbook-archive"><div class="nav wb-nav"><button class="l" aria-label="返回" onclick="back()">‹</button><div class="t"><b>世界书</b><small>LORE ARCHIVE</small></div><div class="r"><button onclick="worldbookCategoryManage()">分类</button><span>│</span><button onclick="worldbookImportFile()">导入</button><button class="wb-plus" aria-label="新建世界书" onclick="editWorld()">＋</button></div></div><div class="wb-scroll"><section class="wb-hero"><i class="wb-art wb-art-0" aria-hidden="true"></i><div><h2>猫猫档案库</h2><p>把角色需要记住的世界，整理在这里。</p></div><div class="wb-stats"><span><b>${all.length}</b><small>本</small></span><span><b>${all.filter(w=>w.enabled).length}</b><small>启用</small></span></div></section><button class="wb-helpbar" onclick="worldbookHelp()" title="分类只方便你整理和查看，不改变生效规则"><i>ⓘ</i><span>世界书会为角色补充共享设定与常识</span><b>查看说明 ›</b></button><label class="wb-search"><span aria-hidden="true"><svg viewBox="0 0 32 28"><path d="M10 8q6-3 12 0l-6 7Z" fill="currentColor"/><path d="M16 14v4m0 0q-4 6-8 0m8 0q4 6 8 0M2 12l6 2M1 18l7-1M24 14l6-2m-6 5 7 1" fill="none" stroke="currentColor" stroke-width="1.3"/></svg></span><input type="search" id="wb_search" placeholder="搜索世界书" aria-label="搜索世界书" value="${worldbookAttr(_worldbookSearch)}" oninput="worldbookSearchSet(this.value)"></label><div class="wb-tabs" role="group" aria-label="世界书分类">${chip('all','全部')}${chip('uncategorized','未分类')}${categories.map(x=>chip(String(x.id),String(x.name))).join('')}</div>
 ${(system||pinned.length)?`<section class="wb-group"><header><h3>常用档案</h3><span>${pinned.length+(system?1:0)} 个档案</span></header>${system?`<article class="wb-row wb-system"><button type="button" class="wb-row-main" onclick="worldbookScopeSettings()"><i class="wb-art wb-art-1" aria-hidden="true"></i><span><b>允许这些软件吃世界书</b><small>已允许 ${WORLD_SCOPE_OPTIONS.filter(([k])=>worldbookScopeOn(k)).length} 类软件使用设定</small></span></button><button type="button" class="wb-switch ${worldbookScopesOn()?'on':''}" role="switch" aria-checked="${worldbookScopesOn()}" aria-label="允许软件使用世界书" onclick="worldbookScopesToggle()"><i></i></button><button type="button" class="wb-more" aria-label="共享范围更多操作" onclick="worldbookScopeSettings()">···</button></article>`:''}${pinned.map(card).join('')}</section>`:''}
 ${other.length?`<section class="wb-group"><header><h3>其他档案</h3><span>${other.length} 个档案</span></header>${other.map(card).join('')}</section>`:(!pinned.length&&!system?'<div class="wb-empty">'+(q?'没有找到匹配的档案':all.length?'这个分类里还没有内容':'还没有世界书，点下方新建档案')+'</div>':'')}
 <button class="wb-create" onclick="editWorld()"><span><svg viewBox="0 0 32 32"><path d="M3 11q7-2 13 2 6-4 13-2v18q-7-3-13 0-6-3-13 0Zm13 2v16M8 10 9 3l6 6m4 0 6-6 1 7"/></svg></span>新建世界书</button><div class="wb-footer" aria-hidden="true"></div></div></div>`;
}
function toggleWorld(id){const w=S.worldbook.find(x=>x.id===id);if(!w)return;w.enabled=!w.enabled;save();render();}
function editWorld(id){const w=id?S.worldbook.find(x=>x.id===id):{id:uid(),name:'',keys:'',content:'',enabled:true,always:false,contacts:[],categoryId:_worldbookCategoryFilter!=='all'&&_worldbookCategoryFilter!=='uncategorized'?_worldbookCategoryFilter:'',_new:true};
  if(!w)return;const wc=w.contacts||[];const cs=S.contacts.filter(c=>!c.deleted),categoryId=worldbookEntryCategoryId(w),categories=worldbookCategoryRows();
  worldbookModal(`<h3>${id?'编辑':'新建'}世界书</h3>
    <div class="field"><label>名称</label><input id="w_name" value="${worldbookAttr(w.name)}" placeholder="比如：世界观/某个地点"></div>
    <div class="field"><label>分类（只用于整理查看）</label><select id="w_category" style="width:100%;border:1px solid #38383a;border-radius:8px;padding:9px;background:#2c2c2e;color:#eee"><option value="">未分类</option>${categories.map(x=>`<option value="${worldbookAttr(x.id)}" ${String(x.id)===categoryId?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div>
    <div class="field"><label>触发关键词（逗号分隔，常驻可不填）</label><input id="w_keys" value="${worldbookAttr(w.keys)}" placeholder="苏州,公司"></div>
    <div class="field"><label>内容</label><textarea id="w_content" rows="4">${esc(w.content)}</textarea></div>
    <div class="field"><label class="avline">常驻（每次都生效）<span class="sw ${w.always?'on':''}" id="w_always" onclick="this.classList.toggle('on')"></span></label></div>
    <div class="field"><label>对谁生效（都不选=所有角色共享）</label>
      ${cs.length?cs.map(c=>`<label class="avline" style="font-weight:400">${esc(c.remark||c.name)}<span class="sw ${wc.indexOf(c.id)>=0?'on':''}" data-ct="${c.id}" onclick="this.classList.toggle('on')"></span></label>`).join(''):'<div style="font-size:12px;color:#999">还没有角色</div>'}</div>
    <div class="btns"><button class="btn g" onclick="closeModal()">取消</button><button class="btn p" onclick="saveWorld(${worldbookActionId(w.id)},${!!w._new})">保存</button></div>
    ${id?`<button class="btn d" style="margin-top:10px" onclick="worldbookDeleteAsk(${worldbookActionId(w.id)})">删除</button>`:''}`);}
function saveWorld(id,isNew){const contacts=[...document.querySelectorAll('[data-ct].on')].map(e=>e.getAttribute('data-ct')),selected=String($('#w_category')&&$('#w_category').value||''),categoryId=worldbookCategoryRows().some(x=>String(x.id)===selected)?selected:'';
  const w={id,name:$('#w_name').value.trim()||'未命名',keys:$('#w_keys').value.trim(),content:$('#w_content').value.trim(),enabled:true,always:$('#w_always').classList.contains('on'),contacts,categoryId};
  if(isNew)S.worldbook.push(w);else{const i=S.worldbook.findIndex(x=>x.id===id);if(i<0)return;w.enabled=S.worldbook[i].enabled;w.pinned=!!S.worldbook[i].pinned;S.worldbook[i]=w;}
  save();closeModal();render();}
function delWorld(id){S.worldbook=S.worldbook.filter(x=>x.id!==id);save();closeModal();render();}
function worldbookCategoryManage(){const rows=worldbookCategoryRows();worldbookModal(`<h3>世界书分类</h3><div class="hint">分类只改变列表的整理方式，不会改变任何世界书的顺序、生效条件或作用角色。适合按“人物、地点、规则、剧情、资料”等你自己的习惯创建。</div><div class="field" style="display:flex;gap:8px;align-items:center"><input id="worldbook_category_new" maxlength="24" placeholder="新分类名称" style="min-width:0;flex:1"><button class="minibtn" onclick="worldbookCategoryCreate()">添加</button></div><div style="max-height:46vh;overflow:auto">${rows.length?rows.map(x=>{const n=(S.worldbook||[]).filter(w=>worldbookEntryCategoryId(w)===String(x.id)).length;return `<div class="section"><div class="it"><span style="flex:1;min-width:0"><b>${esc(x.name)}</b><small style="display:block;color:#888">${n} 条</small></span><button class="minibtn" onclick="worldbookCategoryRename(${worldbookActionId(x.id)})">改名</button><button class="minibtn" style="color:#ff6b6b" onclick="worldbookCategoryDelete(${worldbookActionId(x.id)})">删除</button></div></div>`;}).join(''):'<div class="empty" style="padding:20px">还没有自定义分类</div>'}</div><button class="btn g" style="margin-top:10px" onclick="closeModal();render()">完成</button>`);}
function worldbookCategoryCreate(){const el=$('#worldbook_category_new'),name=worldbookCategoryCleanName(el&&el.value),err=worldbookCategoryNameError(name);if(err){toast(err);return;}S.worldbookCategories=Array.isArray(S.worldbookCategories)?S.worldbookCategories:[];S.worldbookCategories.push({id:uid(),name});save();worldbookCategoryManage();toast('已添加分类');}
function worldbookCategoryRename(id){const row=worldbookCategoryRows().find(x=>String(x.id)===String(id));if(!row)return;worldbookModal(`<h3>修改分类名称</h3><div class="field"><input id="worldbook_category_rename" maxlength="24" value="${worldbookAttr(row.name)}"></div><div class="btns"><button class="btn g" onclick="worldbookCategoryManage()">返回</button><button class="btn p" onclick="worldbookCategoryRenameSave(${worldbookActionId(id)})">保存</button></div>`);}
function worldbookCategoryRenameSave(id){const row=worldbookCategoryRows().find(x=>String(x.id)===String(id)),el=$('#worldbook_category_rename'),name=worldbookCategoryCleanName(el&&el.value),err=worldbookCategoryNameError(name,id);if(!row)return;if(err){toast(err);return;}row.name=name;save();worldbookCategoryManage();toast('分类名称已保存');}
async function worldbookCategoryDelete(id){const row=worldbookCategoryRows().find(x=>String(x.id)===String(id));if(!row)return;const n=(S.worldbook||[]).filter(w=>String(w&&w.categoryId||'')===String(id)).length;if(!await uiConfirm('删除分类“'+row.name+'”？\n'+(n?('其中 '+n+' 条世界书会回到“未分类”，内容不会删除。'):'这个空分类会被删除。')))return;(S.worldbook||[]).forEach(w=>{if(String(w&&w.categoryId||'')===String(id))w.categoryId='';});S.worldbookCategories=(S.worldbookCategories||[]).filter(x=>String(x&&x.id)!==String(id));if(_worldbookCategoryFilter===String(id))_worldbookCategoryFilter='uncategorized';save();closeModal();render();toast('分类已删除，世界书内容仍保留');}
function worldbookFileBase(name){return String(name||'导入世界书').replace(/\.[^.]+$/,'').trim()||'导入世界书';}
function worldbookJSONList(data){if(Array.isArray(data))return data;if(!data||typeof data!=='object')return[];if(Array.isArray(data.worldbook))return data.worldbook;let e=data.entries||(data.character_book&&data.character_book.entries)||(data.data&&data.data.character_book&&data.data.character_book.entries);if(Array.isArray(e))return e;if(e&&typeof e==='object')return Object.values(e);if(data.content||data.text||data.description)return[data];return[];}
function worldbookImportRows(data,fileName,plainText){const base=worldbookFileBase(fileName);if(data==null){const content=String(plainText||'').replace(/^\uFEFF/,'').trim();return content?[{name:base,keys:'',content:content.slice(0,100000),enabled:true,always:true,contacts:[]}]:[];}return worldbookJSONList(data).slice(0,500).map((x,i)=>{x=x&&typeof x==='object'?x:{};let keys=x.keys!=null?x.keys:(x.key!=null?x.key:(x.keywords!=null?x.keywords:''));if(Array.isArray(keys))keys=keys.join(',');else keys=String(keys||'');let content=x.content!=null?x.content:(x.text!=null?x.text:(x.description!=null?x.description:''));if(content&&typeof content==='object')content=JSON.stringify(content);content=String(content||'').trim().slice(0,100000);const contacts=Array.isArray(x.contacts)?x.contacts.filter(cid=>(S.contacts||[]).some(c=>c&&!c.deleted&&c.id===cid)):[];return{name:String(x.name||x.comment||x.title||(base+(i?' '+(i+1):''))).trim().slice(0,80)||base,keys:keys.trim().slice(0,1000),content,enabled:x.enabled!==false&&x.disable!==true,always:x.always===true||x.constant===true||!keys.trim(),contacts};}).filter(x=>x.content);}
function worldbookReadText(f){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result||''));r.onerror=()=>reject(new Error('文件读取失败，请重新选择'));r.readAsText(f);});}
function worldbookMergeRows(rows){S.worldbook=S.worldbook||[];let added=0,skipped=0;rows.forEach(w=>{const duplicate=S.worldbook.some(x=>x&&String(x.name||'').trim()===w.name&&String(x.keys||'').trim()===w.keys&&String(x.content||'').trim()===w.content);if(duplicate){skipped++;return;}S.worldbook.push(Object.assign({},w,{id:uid(),categoryId:''}));added++;});if(added){save();render();}toast(added?'已导入 '+added+' 条世界书'+(skipped?'，跳过 '+skipped+' 条重复内容':''):(skipped?'这些内容已经导入过了':'文件里没有可导入的世界书内容'));return{added,skipped};}
async function worldbookImportRead(f){try{if(!f)throw new Error('没有选择文件');if((+f.size||0)>4*1024*1024)throw new Error('文件超过 4MB，请拆分后再导入');const text=await worldbookReadText(f),isJson=/\.json$/i.test(f.name||'')||/json/i.test(f.type||'');let data=null;if(isJson){try{data=JSON.parse(text.replace(/^\uFEFF/,''));}catch(_){throw new Error('JSON 格式不正确，请检查文件后重试');}}const rows=worldbookImportRows(data,f.name,text);worldbookMergeRows(rows);}catch(e){toast((e&&e.message)||'世界书文件导入失败');}}
function worldbookImportFile(){pickFile('.json,.txt,.md,application/json,text/plain,text/markdown',f=>worldbookImportRead(f));}

/* ---------- 查他手机 ---------- */
function openSpy(){if(S.couple&&S.couple.cid&&getC(S.couple.cid)){go('spy',{id:S.couple.cid});return;}
  toast('查手机只对恋人开放💞 先去角色资料页绑定情侣空间');}
