    const add=(kind,list,api)=>{for(const o of list||[]){if(String(o.accountId||'main')!==account)continue;const own=NorthHotelData.roleOrder(o)&&String(o.cid)===String(id),party=(o.people||[]).some(p=>p.id==='role:'+id)||kind==='hotel'&&tvHotelVisibleToRole(o,id);if(!own&&!party)continue;if(api&&!(kind==='ticket'?api.visible(o,'ticket'):api.visible(o)))continue;if(kind==='hotel'&&typeof NorthTravelOrders!=='undefined'&&!NorthTravelOrders.visible(o,'hotel'))continue;entries.push({kind,o,own,api});}};
